// TH16 v1.00a source bullet types used by this card (transcribe/th16/touhou-bullets.ecl,
// approved 2026-11-07 reuse of the identical TH18 slot; see bullet-types.md).
// BossCard1_at:343 etSprite(0, 8, 6) -> source type 8, color 6.
const TH16_RICE: int = 480;

// TH16 v1.00a Stage 2 boss, source st02bs.ecl.txt BossCard1:273-336.
// Spell 8-11 all enter BossCard1 (Boss:34-38, SPELL_ID 8..11, lifeSet(2100)); only the
// declared spell name differs between E/N and H/L.
//
// Source timeline (t = frames from card start):
//   t=0    reset state, setInterrupt(0,0,1800,"Boss2"), spell(8,1800)
//          movePosTime(60,4,(0,128)) + moveLimit(0,128,240,64)
//   t=90   @BossCard1_at(_f(1)) async, then wait(120)/moveRand(60,4,1.0)/wait(80) loop
//   t=1800 segment ends (HP depletion or Boss2 interrupt)
//
// Omitted by the common transcription policy: entry etCancel/etClear/enmKillAll/killAllAsync
// (previous card field and tasks), stars/dropSeason/BossItemCard (rewards), anm316/anmPlay/
// playSound (presentation), spell declaration and MISS/BOMB/CAPTURE bookkeeping.

const TIME_LIMIT: int = 1924;      // 120 shell buffer + 1800 source window + 4 startup slack
const OPENING_BUFFER: int = 120;
const BOSS_HP: int = 2100;         // Boss:36 lifeSet(2100) for SPELL_ID 8..11

// BossCard1:311 moveLimit(0,128,240,64): width/height are full sizes, so the clamped
// rectangle is x in [-120,120], y in [96,160]. The moveRand direction branches use the
// inner quarter-size zone (movement.md): x +-60, y 112..144.
const MOVE_EDGE_X: fx = 120fx;
const MOVE_EDGE_TOP: fx = 96fx;
const MOVE_EDGE_BOTTOM: fx = 160fx;
const MOVE_INNER_X: fx = 60fx;

// ---------------- source BossCard1_at: rotating rain ring ----------------

// BossCard1_at:365-367 EX list, in order: ANIM(1), BOUNCE(1,13,1.0), VELTIME(120,2.0,90deg).
// ANIM a=1 is the birth retreat position -= 4*velocity; it is folded into the spawn distance
// below (net = etDist - 4*initial speed, aim-modes.md "出生距离与ANIM退位移").
// BOUNCE wall mask U/L/R = source 1|4|8 -> target left/right/up/down 1/2/4/8 => 7, one event.
// VELTIME adds delta = (target 2.0 - initial speed) / 120 along 90deg (screen down) each of
// 120 frames; target expresses it as a cartesian per-frame velocity increment.
xformdef RAIN_VEL(g: fx) {
    bounce_arm(7, 1);
    set_gravity(0fx, g);
    wait(120);
    set_gravity(0fx, 0fx);
}

// BOUNCE r=1.0 (BossCard1_at:366) sets the post-bounce scalar speed to 1.0. bounce_arm only
// mirrors the bullet, so this per-bullet task applies the speed change on the first frame the
// reflected bullet is still next to the wall (one frame after the crossing).
async sub rice_bounce() {
    loop {
        wait(1);
        if $self_x <= -186fx && $self_vx > 0fx { set_speed(0, 1fx); return; }
        if $self_x >= 186fx && $self_vx < 0fx { set_speed(0, 1fx); return; }
        if $self_y <= 6fx && $self_vy > 0fx { set_speed(0, 1fx); return; }
    }
}

// BossCard1_at:338-395. Emitter: etAim(0,3) fixed-direction ring, etSprite(0,8,6).
// per rank: count 12/16/16/16, speed 1.5/2.0/2.6/2.6, interval 60/45/28/20.
async sub rain() {
    var n: int = 16;
    var speed: fx = 2.6fx;
    var interval: int = 28;
    var rank: int = global(GVAR_RANK);
    if rank == RANK_EASY {
        n = 12;
        speed = 1.5fx;
        interval = 60;
    } else if rank == RANK_NORMAL {
        n = 16;
        speed = 2.0fx;
        interval = 45;
    } else if rank == RANK_HARD {
        n = 16;
        speed = 2.6fx;
        interval = 28;
    } else {
        n = 16;
        speed = 2.6fx;
        interval = 20;
    }
    var g: fx = (2fx - speed) / 120;   // VELTIME slope toward scalar speed 2.0 over a=120
    var retreat: fx = speed * 4fx;     // ANIM a=1: position -= 4 * initial velocity
    var c: int = 0;                    // source %C, BAM
    var d: int = 182;                  // source %D = 0.017453 rad
    var e: fx = 0fx;                   // source %E
    // BossCard1_at:392-393 `if ($G--)` starts at 2000; at the longest interval that is far
    // beyond the 1800-frame window, so the wave queue is bounded by the boss task lifetime.
    loop {
        var dist: fx = e - retreat;
        for i in 0..n {
            var ang: angle = (c + (i * 65536) / n) as angle;
            var x: fx = $self_x + dist * cos(ang);
            var y: fx = $self_y + dist * sin(ang);
            _ = fire(TH16_RICE, 6, x, y, speed, ang, RAIN_VEL(g), rice_bounce);
        }
        c = c + d;
        d = d + 8101;                  // 0.776644 rad
        e = e + 0.7fx;
        wait(interval);
    }
}

// ---------------- source BossCard1: entry state and movement ----------------

// 412 moveRand(60,4,1.0) recipe (movement.md): one signed direction sample per call, linear
// speed 1-k/60 over 60 movement ticks, position clamped to the moveLimit rectangle each tick.
// The direction interior is the quarter-size zone around the limit centre.
sub arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = (60 - k) as fx / 60; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -MOVE_EDGE_X { nx = -MOVE_EDGE_X; }
    if nx > MOVE_EDGE_X { nx = MOVE_EDGE_X; }
    if ny < MOVE_EDGE_TOP { ny = MOVE_EDGE_TOP; }
    if ny > MOVE_EDGE_BOTTOM { ny = MOVE_EDGE_BOTTOM; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    arm_next_step();
}

sub move_rand() {
    var r: int = rand(65536) - 32768;   // signed unit random * pi, unwrapped BAM
    var a: int = r / 3;
    if $self_x < -MOVE_INNER_X {
        a = r / 3;
    } else if $self_x > MOVE_INNER_X {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // native +-pi/2 guard, epsilon 0.05 rad (nearest BAM boundaries)
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    begin_angle(a as angle);
}

sub cwait(frames: int) {
    for i in 0..frames {
        wait(1);
        arm_next_step();
    }
}

// Boss entry: Boss:26-27 setHurtbox(40,40) / setHitbox(48,48); plain-circle source values are
// halved for the target radii (enemy-state.md).
async sub boss_main() {
    set_invuln(65535);                 // training shell: real enemy is invulnerable
    set_hurtbox(20fx);
    set_hitbox(24fx);
    // t=0 movePosTime(60,4,(0,128)) is zero displacement from this spawn point, and the
    // moveLimit rectangle is applied per tick inside arm_next_step().
    wait(90);
    spawn rain();                       // BossCard1:320 @BossCard1_at(_f(1)) async
    for cycle in 0..8 {                 // moveRand at t = 210, 410, ... 1610
        cwait(120);                     // BossCard1:325 wait(120)
        move_rand();                    // BossCard1:326 moveRand(60,4,1.0)
        cwait(80);                      // BossCard1:327 wait(80)
    }
    cwait(110);                         // 90 + 8*200 = 1690; segment end at 1800
}

// ---------------- standalone-card shell (validation.md) ----------------

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, BOSS_HP, 0, 0, 0, boss_main);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
